150	function normalizeCloudEvalPrompt(prompt: unknown): string {
151	  if (typeof prompt === 'string') {
152	    return prompt;
153	  }
154	  if (isRecord(prompt)) {
155	    if (typeof prompt.content === 'string') {
156	      return prompt.content;
157	    }
158	    if (typeof prompt.raw === 'string') {
159	      return prompt.raw;
160	    }
161	  }
162	  return String(prompt ?? '');
163	}
