/**
 * Returns the team with the earliest createdAt date (the oldest team).
 */
function pickOldestTeam(teams: AccessibleTeam[]): AccessibleTeam {
  return [...teams].sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
  )[0];
}

/**
 * Finds a team matching the given identifier, checking id first, then case-insensitive
 * display name, then slug (in that priority order).
 */
function findTeamByIdentifier(
  teams: AccessibleTeam[],
  identifier: string,
): AccessibleTeam | undefined {
  return (
    teams.find((t) => t.id === identifier) ??
    teams.find((t) => t.name.toLowerCase() === identifier.toLowerCase()) ??
    teams.find((t) => t.slug === identifier)
  );
}

/**
 * Selects a team from a list scoped to a single organization. With a single team it is
 * returned directly. With multiple teams, non-interactive environments (and cancelled
 * interactive prompts) fall back to the oldest team rather than calling the cloud API.
 */
async function selectTeamInteractively(
  teams: AccessibleTeam[],
): Promise<{ team: AccessibleTeam; suffix?: string }> {
  if (teams.length === 1) {
    return { team: teams[0] };
  }

  if (isNonInteractive()) {
    // Non-interactive (CI): use the oldest team but warn.
    const oldest = pickOldestTeam(teams);
    logger.warn(
      chalk.yellow(`\n⚠️  You have access to ${teams.length} teams. Using '${oldest.name}'.`),
    );
    logger.info(chalk.dim(`   Use --team flag to specify: promptfoo auth login --team <name>`));
    return { team: oldest };
  }

  try {
    const answer = await select({
      message: 'Select a team to use:',
      choices: teams.map((team) => ({
        name: team.name,
        value: team.id,
        description: team.slug,
      })),
    });
    const chosen = teams.find((t) => t.id === answer);
    if (chosen) {
      return { team: chosen };
    }
    return { team: pickOldestTeam(teams), suffix: '(default)' };
  } catch {
    // User cancelled (Ctrl+C) - use the oldest team.
    return { team: pickOldestTeam(teams), suffix: '(default)' };
