}

/**
 * Resolves organization and team context after token validation. Persists the resolved
 * organization, cached team list, and selected team to the cloud config.
 * @returns The resolved team on success, or null when resolution fails (already logged).
 * @throws Error for unexpected failures (e.g. an unknown --team identifier).
 */
async function resolveOrgAndTeamContext(opts: {
  apiHost: string;
  apiKey: string;
  orgId?: string;
  teamIdentifier?: string;
  fallbackOrganizationId: string;
}): Promise<{ organizationId: string; team?: AccessibleTeam } | null> {
  const { apiHost, apiKey, orgId, teamIdentifier, fallbackOrganizationId } = opts;

  const allTeams = await getUserTeams(apiHost, apiKey);

  // --org provided: restrict all team resolution to the given organization.
  if (orgId) {
    const orgTeams = allTeams.filter((t) => t.organizationId === orgId);
    if (orgTeams.length === 0) {
