      ];
      logger.error(
        `Authentication failed: Organization '${orgId}' not found in your accessible teams. Available organizations: ${availableOrgIds.join(', ')}`,
      );
      return null;
    }

    cloudConfig.setCurrentOrganization(orgId);
    cloudConfig.cacheTeams(orgTeams, orgId);

    if (teamIdentifier) {
      const team = findTeamByIdentifier(orgTeams, teamIdentifier);
      if (!team) {
        throw new Error(
          `Team '${teamIdentifier}' not found. Available teams: ${orgTeams.map((t) => t.name).join(', ')}`,
        );
      }
      cloudConfig.setCurrentTeamId(team.id, orgId);
      logger.info(`Team: ${chalk.cyan(team.name)}`);
      return { organizationId: orgId, team };
    }

    const { team, suffix } = await selectTeamInteractively(orgTeams);
    cloudConfig.setCurrentTeamId(team.id, orgId);
    logger.info(`Team: ${chalk.cyan(team.name)}${suffix ? ` ${chalk.dim(suffix)}` : ''}`);
    return { organizationId: orgId, team };
  }

  // --team provided without --org: search across all accessible organizations.
  if (teamIdentifier) {
    const team = findTeamByIdentifier(allTeams, teamIdentifier);
    if (!team) {
      throw new Error(
        `Team '${teamIdentifier}' not found. Available teams: ${allTeams.map((t) => t.name).join(', ')}`,
      );
    }
    const organizationId = team.organizationId;
    const orgTeams = allTeams.filter((t) => t.organizationId === organizationId);
    cloudConfig.setCurrentOrganization(organizationId);
    cloudConfig.cacheTeams(orgTeams, organizationId);
    cloudConfig.setCurrentTeamId(team.id, organizationId);
    logger.info(`Team: ${chalk.cyan(team.name)}`);
    return { organizationId, team };
  }

  // No flags: prefer the default organization from the token validation response.
  let organizationId = fallbackOrganizationId;
  let orgTeams = allTeams.filter((t) => t.organizationId === organizationId);

  if (orgTeams.length === 0 && allTeams.length > 0) {
    // Default org has no accessible teams; resolve to the org of the oldest team.
    const oldest = pickOldestTeam(allTeams);
    organizationId = oldest.organizationId;
    orgTeams = allTeams.filter((t) => t.organizationId === organizationId);
    cloudConfig.setCurrentOrganization(organizationId);
    cloudConfig.cacheTeams(orgTeams, organizationId);
    logger.info(`Organization: ${chalk.cyan(organizationId)}`);
  } else {
    cloudConfig.setCurrentOrganization(organizationId);
    cloudConfig.cacheTeams(orgTeams, organizationId);
  }

  if (orgTeams.length === 0) {
    // No accessible teams at all - nothing to select.
    return { organizationId };
  }

  const { team, suffix } = await selectTeamInteractively(orgTeams);
  cloudConfig.setCurrentTeamId(team.id, organizationId);
  logger.info(`Team: ${chalk.cyan(team.name)}${suffix ? ` ${chalk.dim(suffix)}` : ''}`);
  return { organizationId, team };
}

